{"edits":[{"path":"openclaw_runtime/src/agents/rate-circuit-breaker.ts","content":"export type RateCircuitState = "closed" | "open" | "half-open";

export type RateCircuitDecisionReason =
  | "allowed"
  | "circuit-open"
  | "probe-in-flight";

export interface RateCircuitDecision {
  readonly allowed: boolean;
  readonly state: RateCircuitState;
  readonly reason: RateCircuitDecisionReason;
  /**
   * Identifies the single half-open probe. It is null for normal requests.
   * Callers should pass the decision returned by beforeRequest to the
   * corresponding record* method so that a late result cannot affect a
   * newer probe.
   */
  readonly probeId: string | null;
}

export interface RateCircuitBreakerOptions {
  /** Number of failures in the sliding window required to open the circuit. */
  readonly failureThreshold: number;
  /** Length of the sliding failure window, in milliseconds. */
  readonly failureWindowMs: number;
  /** Time the circuit remains open before a probe is admitted, in milliseconds. */
  readonly cooldownMs: number;
  /**
   * Monotonic clock used by the breaker. Injecting the clock makes the
   * state machine deterministic and replayable in tests and harnesses.
   */
  readonly now?: () => number;
}

export interface RateCircuitBreaker {
  readonly state: RateCircuitState;
  readonly failureCount: number;
  beforeRequest(): RateCircuitDecision;
  recordSuccess(decision?: RateCircuitDecision): void;
  recordFailure(decision?: RateCircuitDecision): void;
}

const DEFAULT_NOW = (): number => Date.now();

function assertPositiveInteger(name: string, value: number): void {
  if (!Number.isSafeInteger(value) || value <= 0) {
    throw new RangeError(`${name} must be a positive safe integer`);
  }
}

function assertClock(now: number): void {
  if (!Number.isFinite(now) || now < 0) {
    throw new RangeError("the injected clock must return a finite, non-negative number");
  }
}

/**
 * Creates an opt-in rate circuit breaker.
 *
 * The breaker is deliberately a rate boundary only. It does not perform
 * requests and therefore cannot relax SSRF, loop-guard, approval, budget, or
 * any other caller-side authorization checks. A denied request must not be
 * given to recordFailure or recordSuccess because it had no effect.
 */
export function createRateCircuitBreaker(
  options: RateCircuitBreakerOptions,
): RateCircuitBreaker {
  assertPositiveInteger("failureThreshold", options.failureThreshold);
  assertPositiveInteger("failureWindowMs", options.failureWindowMs);
  assertPositiveInteger("cooldownMs", options.cooldownMs);

  const clock = options.now ?? DEFAULT_NOW;
  let state: RateCircuitState = "closed";
  let failures: number[] = [];
  let openedAt = 0;
  let probeInFlight = false;
  let nextProbeId = 1;

  const currentTime = (): number => {
    const value = clock();
    assertClock(value);
    return value;
  };

  const pruneFailures = (now: number): void => {
    const cutoff = now - options.failureWindowMs;
    failures = failures.filter((timestamp) => timestamp > cutoff);
  };

  const refresh = (now: number): void => {
    pruneFailures(now);
    if (state === "open" && now - openedAt >= options.cooldownMs) {
      state = "half-open";
      probeInFlight = false;
    }
  };

  const transitionToOpen = (now: number): void => {
    state = "open";
    openedAt = now;
    probeInFlight = false;
  };

  const transitionToClosed = (): void => {
    state = "closed";
    failures = [];
    probeInFlight = false;
  };

  const isCurrentDecision = (
    decision: RateCircuitDecision | undefined,
    expectedProbeId: string | null,
  ): boolean => {
    if (decision === undefined) {
      return true;
    }
    return (
      decision.allowed &&
      decision.probeId === expectedProbeId &&
      decision.state === expectedProbeId === null ? true : decision.probeId === expectedProbeId
    );
  };

  const breaker: RateCircuitBreaker = {
    get state(): RateCircuitState {
      refresh(currentTime());
      return state;
    },

    get failureCount(): number {
      refresh(currentTime());
      return failures.length;
    },

    beforeRequest(): RateCircuitDecision {
      const now = currentTime();
      refresh(now);

      if (state === "open") {
        return {
          allowed: false,
          state,
          reason: "circuit-open",
          probeId: null,
        };
      }

      if (state === "half-open") {
        if (probeInFlight) {
          return {
            allowed: false,
            state,
            reason: "probe-in-flight",
            probeId: null,
          };
        }

        probeInFlight = true;
        const probeId = `probe-${nextProbeId++}`;
        return {
          allowed: true,
          state,
          reason: "allowed",
          probeId,
        };
      }

      return {
        allowed: true,
        state,
        reason: "allowed",
        probeId: null,
      };
    },

    recordSuccess(decision?: RateCircuitDecision): void {
      const now = currentTime();
      refresh(now);

      if (state === "half-open") {
        if (probeInFlight && isCurrentDecision(decision, decision?.probeId ?? null)) {
          transitionToClosed();
        }
        return;
      }

      // A success does not erase failures in a closed sliding window. This
      // keeps the breaker based on the rate of failures rather than on
      // consecutive outcomes.
    },

    recordFailure(decision?: RateCircuitDecision): void {
      const now = currentTime();
      refresh(now);

      if (state === "half-open") {
        if (probeInFlight && isCurrentDecision(decision, decision?.probeId ?? null)) {
          transitionToOpen(now);
        }
        return;
      }

      if (state !== "closed") {
        return;
      }

      if (decision !== undefined && !decision.allowed) {
        return;
      }

      failures.push(now);
      pruneFailures(now);
      if (failures.length >= options.failureThreshold) {
        transitionToOpen(now);
      }
    },
  };

  return breaker;
}

/** Alias for consumers that prefer a constructor-like factory name. */
export const createRateCircuitBreakerWithClock = createRateCircuitBreaker;
