        probeInFlight = true;
        const probeId = `probe-${nextProbeId++}`;
        return {
          allowed: true,
          state,
          reason: "allowed",
          probeId,
        };
      }

      return {
        allowed: true,
        state,
        reason: "allowed",
        probeId: null,
      };
    },

